function normalizeLines(value) {
  return String(value || "").split("\n").map((item) => item.trim()).filter(Boolean);
}

function jobKey(job) {
  return job.source + ":" + (job.id || job.url || [job.title, job.company].filter(Boolean).join("|"));
}

/* src/content/adapters.js */
function text(element) { return element?.textContent?.replace(/\s+/g, " ").trim() || null; }
function absoluteUrl(href) { try { return new URL(href, location.href).href; } catch { return null; } }

function extractLinkedIn() {
  const cards = [...document.querySelectorAll("li.jobs-search-results__list-item, .job-card-container")];
  return cards.map((card, index) => {
    const link = card.querySelector("a[href*='/jobs/view/']");
    const age = text(card.querySelector("time"));
    return {
      source: "linkedin", id: link?.getAttribute("data-job-id") || link?.href?.match(/\d+/)?.[0] || String(index),
      url: absoluteUrl(link?.href), title: text(card.querySelector(".job-card-list__title, .artdeco-entity-lockup__title, strong")),
      company: text(card.querySelector(".job-card-container__company-name, .artdeco-entity-lockup__subtitle")),
      location: text(card.querySelector(".job-card-container__metadata-item, .artdeco-entity-lockup__caption")),
      postedText: age, description: null, coverage: "card"
    };
  });
}

function extractGreenhouse() {
  const links = [...document.querySelectorAll("a[href*='/jobs/']")];
  return links.map((link, index) => ({
    source: "greenhouse", id: link.href.match(/jobs\/(\d+)/)?.[1] || String(index), url: absoluteUrl(link.href),
    title: text(link), company: document.title.split("|")[0]?.trim() || null,
    location: text(link.closest("div")?.querySelector(".location")), postedText: null, description: null, coverage: "card"
  })).filter((job) => job.title);
}

function extractLever() {
  const links = [...document.querySelectorAll("a[href*='/']")].filter((link) => link.closest(".posting"));
  return links.map((link, index) => ({
    source: "lever", id: link.href.split("/").filter(Boolean).pop() || String(index), url: absoluteUrl(link.href),
    title: text(link.querySelector("h5, .posting-title, div")) || text(link), company: document.title.split("|")[0]?.trim() || null,
    location: text(link.querySelector(".sort-by-location, .posting-categories")), postedText: null, description: null, coverage: "card"
  })).filter((job) => job.title);
}

function extractLoadedJobs() {
  if (location.hostname === "www.linkedin.com") return extractLinkedIn();
  if (location.hostname.endsWith("greenhouse.io")) return extractGreenhouse();
  if (location.hostname === "jobs.lever.co") return extractLever();
  return [];
}

function pageDescription() {
  return text(document.querySelector(
    ".jobs-description-content__text, .jobs-description__content, #content, .section-wrapper .content, .posting-page, .posting"
  ));
}

function selectedLinkedInId() {
  const selected = document.querySelector("a.jobs-search-results__list-item--active[href*='/jobs/view/'], a[aria-current='page'][href*='/jobs/view/']");
  return selected?.href?.match(/\d+/)?.[0] || location.href.match(/jobs\/view\/(\d+)/)?.[1] || null;
}

/**
 * A listing card frequently does not include requirements or work-authorization
 * language. Enrich only the currently selected/full detail so a short card is
 * never treated as a complete job description.
 */
function enrichWithOpenDescription(jobs) {
  const description = pageDescription();
  if (!description || description.length < 120) return jobs;
  if (location.hostname === "www.linkedin.com") {
    const id = selectedLinkedInId();
    return jobs.map((job) => job.id === id ? { ...job, description, coverage: "full_description" } : job);
  }
  if (location.hostname.endsWith("greenhouse.io") || location.hostname === "jobs.lever.co") {
    const current = location.href.replace(/\/$/, "");
    return jobs.map((job) => job.url?.replace(/\/$/, "") === current
      ? { ...job, description, coverage: "full_description" }
      : job);
  }
  return jobs;
}

/* src/content/policy.js */

const NO_SPONSORSHIP = /(?:no|cannot|can't|will not|won't|unable to)\s+(?:provide|offer|sponsor|support).{0,40}(?:visa|sponsorship)|(?:visa|sponsorship).{0,40}(?:not\s+(?:available|offered)|unavailable)/i;

function parseAgeHours(raw) {
  if (!raw) return null;
  const value = raw.trim().toLowerCase();
  const match = value.match(/(\d+)\s*(minute|hour|day|week)s?\s+ago/);
  if (!match) return null;
  const units = { minute: 1 / 60, hour: 1, day: 24, week: 168 };
  return Number(match[1]) * units[match[2]];
}

function includesAny(haystack, needles) {
  const normalized = String(haystack || "").toLowerCase();
  return needles.some((item) => normalized.includes(item.toLowerCase()));
}

function assessJob(job, profile, policy) {
  const reasons = [];
  const age = parseAgeHours(job.postedText);
  if (age !== null && age > policy.maxAgeHours) return result("skip", null, ["Too old"], job);
  if (age === null) reasons.push("Date unknown");

  const body = [job.title, job.description].filter(Boolean).join(" ");
  if (profile.needsSponsorship && NO_SPONSORSHIP.test(body)) return result("skip", null, ["No sponsorship"], job);
  if (profile.needsSponsorship && !job.description) reasons.push("Open description");

  if (policy.allowedLocations.length && job.location && !includesAny(job.location, policy.allowedLocations)) {
    return result("skip", null, ["Location filter"], job);
  }
  if (policy.allowedLocations.length && !job.location) reasons.push("Location unknown");

  const title = String(job.title || "");
  const titleTerms = profile.targetRoles.flatMap((role) => role.toLowerCase().split(/\W+/).filter((term) => term.length > 2));
  const roleMatches = titleTerms.filter((term) => title.toLowerCase().includes(term)).length;
  // Require only one meaningful title term locally. Exact role compatibility
  // belongs to Jev once the full description has been extracted.
  if (profile.targetRoles.length && titleTerms.length && roleMatches === 0) {
    return result("skip", null, ["Wrong role"], job);
  }
  if (!job.description) return result("check", null, reasons.length ? reasons : ["Open description"], job);

  // Placeholder for Jev: replace with an authenticated backend assessment in the next milestone.
  const skillHits = profile.skills.filter((skill) => includesAny(body, [skill])).length;
  const roleHit = profile.targetRoles.length ? Math.min(1, roleMatches / Math.max(1, titleTerms.length)) : 0.5;
  const skillScore = profile.skills.length ? skillHits / profile.skills.length : 0.5;
  const fit = Math.round((10 * (0.6 * roleHit + 0.4 * skillScore)) * 10) / 10;
  if (fit < policy.minimumFit) return result("skip", fit, ["Low match"], job);
  return result("keep", fit, reasons, job);
}

function applyJevAssessment(local, classifier, policy) {
  if (local.decision === "skip") return local;
  if (!classifier?.adequateEvidence) return { ...local, decision: "check", fit: null, reasons: ["Uncertain"] };
  if (classifier.sponsorship === "unavailable") return { ...local, decision: "skip", fit: null, reasons: ["No sponsorship"] };
  const fit = Number(classifier.fit);
  if (!Number.isFinite(fit) || fit < 0 || fit > 10) return { ...local, decision: "check", fit: null, reasons: ["Invalid classification"] };
  if (classifier.confidence < 0.55) return { ...local, decision: "check", fit, reasons: ["Uncertain"] };
  return { ...local, fit, decision: fit >= policy.minimumFit ? "keep" : "skip", reasons: fit >= policy.minimumFit ? [] : ["Low match"] };
}

function result(decision, fit, reasons, job) {
  return { key: jobKey(job), decision, fit, reasons, job };
}

/* src/content/content-script.js */

function badge(result) {
  const node = document.createElement("span");
  node.className = "job-sieve-badge job-sieve-" + result.decision;
  const rating = result.fit === null ? "" : result.fit.toFixed(1) + "/10 · ";
  node.textContent = rating + result.decision.toUpperCase() + (result.reasons[0] ? " · " + result.reasons[0] : "");
  return node;
}

function attachBadges(results, hideSkipped) {
  document.querySelectorAll(".job-sieve-badge").forEach((node) => node.remove());
  document.querySelectorAll("[data-job-sieve-hidden]").forEach((node) => { node.hidden = false; node.removeAttribute("data-job-sieve-hidden"); });
  for (const result of results) {
    const candidateLinks = [...document.querySelectorAll("a[href]")].filter((link) => link.href === result.job.url);
    const target = candidateLinks[0]?.closest("li, .job-card-container, .posting");
    if (!target) continue;
    target.append(badge(result));
    if (hideSkipped && result.decision === "skip") { target.hidden = true; target.dataset.jobSieveHidden = "true"; }
  }
}

async function scan() {
  const settings = await chrome.runtime.sendMessage({ type: "GET_SETTINGS" });
  const jobs = enrichWithOpenDescription(extractLoadedJobs());
  const localResults = jobs.map((job) => assessJob(job, settings.profile, settings.policy));
  const results = await Promise.all(localResults.map(async (local) => {
    if (local.decision === "skip" || !local.job.description) return local;
    const response = await chrome.runtime.sendMessage({ type: "CLASSIFY_JOB", job: local.job });
    return response.ok ? applyJevAssessment(local, response.result, settings.policy) : { ...local, decision: "check", fit: null, reasons: ["Classifier unavailable"] };
  }));
  attachBadges(results, settings.policy.hideSkipped);
  await chrome.runtime.sendMessage({ type: "PAGE_RESULTS", results });
  return results;
}

chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
  if (message.type === "SCAN_PAGE") { scan().then((results) => sendResponse({ ok: true, results })); return true; }
  if (message.type === "RESTORE_SKIPPED") { attachBadges([], false); sendResponse({ ok: true }); }
  return undefined;
});
